const colorPalette = [
  ['#00E96A', '#388E3C'], // Verde
  ['#db001a', '#D32F2F'], // Vermelho
  ['#0031ff', '#1976D2'], // Azul
  ['#FADA0A', '#FBC02D'], // Amarelo
  ['#FA6400', '#F57C00'], // Laranja
  ['#03A9F4', '#0288D1'], // Azul Claro
  ['#9C27B0', '#7B1FA2'], // Roxo
  ['#00BCD4', '#0097A7'], // Ciano
  ['#8BC34A', '#689F38'], // Verde Claro
  ['#FF5722', '#E64A19'], // Laranja Escuro
  ['#795548', '#5D4037']  // Marrom
];

