// ===================================================================================

context.panel.data.series.forEach((series) => {
  const valueField = series.fields.find((f) => f.type === 'number');
  const categoryField = series.fields.find((f) => f.type === 'string');

  if (valueField && categoryField) {
    for (let i = 0; i < valueField.values.length; i++) {
      const category = categoryField.values.get(i);
      const value = valueField.values.get(i);

      if (value === null || value === undefined || isNaN(value)) {
        continue;
      }

      const color = colorPalette[pieChartData.length % colorPalette.length];

      // Adiciona os dados com o itemStyle EXATO do padrão visual
      pieChartData.push({
        name: category,
        value: Math.abs(value),
        itemStyle: {
          color: new context.echarts.graphic.LinearGradient(0, 0, 0, 1, [
            { offset: 0, color: color[0] },
            { offset: 1, color: color[1] }
